class MinStack {
    vector<int> vals;
    vector<int> mins;
public:
    MinStack() {}

    void push(int value) {
        vals.push_back(value);
        if (mins.empty() || value <= mins.back())
            mins.push_back(value);
        else
            mins.push_back(mins.back());
    }

    void pop() {
        vals.pop_back();
        mins.pop_back();
    }

    int top() {
        return vals.back();
    }

    int getMin() {
        return mins.back();
    }
};
